-- ----------------------------
-- Table structure for `etcitem`
-- ----------------------------
DROP TABLE IF EXISTS `etcitem`;
CREATE TABLE `etcitem` (
  `item_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(45) NOT NULL DEFAULT '',
  `note` varchar(255) DEFAULT '' COMMENT '註解',
  `classname` varchar(100) DEFAULT '0' COMMENT '獨立核心',
  `identified_name_id` varchar(45) NOT NULL DEFAULT '',
  `item_type` varchar(40) NOT NULL DEFAULT '',
  `use_type` varchar(20) NOT NULL DEFAULT '',
  `material` varchar(45) NOT NULL DEFAULT '',
  `weight` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '重量',
  `invgfx` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '背包圖示',
  `grdgfx` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '地面圖示',
  `itemdesc_id` int(10) unsigned NOT NULL DEFAULT '0',
  `stackable` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '可以堆疊',
  `max_charge_count` int(10) unsigned NOT NULL DEFAULT '0',
  `max_use_time` int(10) NOT NULL DEFAULT '0',
  `dmg_small` int(10) unsigned NOT NULL DEFAULT '0',
  `dmg_large` int(10) unsigned NOT NULL DEFAULT '0',
  `min_lvl` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '角色幾等以下無法使用',
  `max_lvl` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '角色幾等以上無法使用',
  `use_royal` int(2) NOT NULL DEFAULT '0',
  `use_knight` int(2) NOT NULL DEFAULT '0',
  `use_elf` int(2) NOT NULL DEFAULT '0',
  `use_mage` int(2) NOT NULL DEFAULT '0',
  `use_darkelf` int(2) NOT NULL DEFAULT '0',
  `use_dragonknight` int(2) NOT NULL DEFAULT '0',
  `use_illusionist` int(2) NOT NULL DEFAULT '0',
  `bless` int(2) unsigned NOT NULL DEFAULT '1',
  `trade` int(2) unsigned NOT NULL DEFAULT '0' COMMENT '是否交易0是1否',
  `cant_delete` int(2) unsigned NOT NULL DEFAULT '0' COMMENT '無法刪除',
  `can_seal` int(2) unsigned NOT NULL DEFAULT '0' COMMENT '可封印',
  `delay_id` int(10) unsigned NOT NULL DEFAULT '0',
  `delay_time` int(10) unsigned NOT NULL DEFAULT '0',
  `delay_effect` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '延遲時間',
  `food_volume` int(10) NOT NULL DEFAULT '0',
  `save_at_once` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `enchant_type` int(5) NOT NULL DEFAULT '0' COMMENT '娃娃可以附魔代號',
  `receive` int(10) unsigned NOT NULL DEFAULT '0',
  `record` int(2) DEFAULT '0' COMMENT '是否記錄',
  `deleteRecord` int(2) NOT NULL DEFAULT '0' COMMENT '刪除時進行記錄(0:記錄1:不記錄)',
  `cant_be_sold` tinyint(1) DEFAULT '0' COMMENT '禁止販賣NPC',
  `fight_ban` int(2) DEFAULT '0',
  `Quality1` varchar(255) DEFAULT NULL COMMENT '道具顯示1',
  `Quality2` varchar(255) DEFAULT NULL COMMENT '道具顯示2',
  `Quality3` varchar(255) DEFAULT NULL COMMENT '道具顯示3',
  `Quality4` varchar(255) DEFAULT NULL COMMENT '道具顯示4',
  `Quality5` varchar(255) DEFAULT NULL COMMENT '道具顯示5',
  `Quality6` varchar(255) DEFAULT NULL COMMENT '道具顯示6',
  `Quality7` varchar(255) DEFAULT NULL,
  `Quality8` varchar(255) DEFAULT NULL,
  `Quality9` varchar(255) DEFAULT NULL,
  `Quality10` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`item_id`) USING BTREE,
  KEY `item_id` (`item_id`) USING BTREE
) ENGINE=MyISAM AUTO_INCREMENT=90783905 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

